"""HTTP surface for demo sites, generated by the real Site Magic pipeline.

Per ADR-030 (docs/ADR-030_DEMO_SITES_VIA_SITEMAGIC.md): a demo at
/demos/{slug} is a Site Magic job against a reserved tenant_id
(webstaffr/demo_sites.py), not hand-authored static HTML or the
intake-schema Jinja2 renderer. GET /sites/{tenant_id}/web
(site_render_router.py) renders from intake_submissions and is a
different pipeline entirely -- demos exist to prove Site Magic's actual
output, so they route through Site Magic, not around it.

State machine surfaced to the browser:
  no job yet       -> enqueue, then fall through to "building"
  job in progress   -> 200, lightweight status page (no polling JS yet --
                       first cut is server-rendered refresh via the
                       <meta refresh> tag, simplest thing that works)
  job ready/published -> 302 to the published artifact URL
  job failed        -> 200, apologetic fallback page + logged server-side

No database writes outside the Site Magic tables DemoJobManager already
owns. No customer-facing form submission -- demos are read-only; the
"is this legit" question a prospect might have about submitting a form
belongs to the real intake flow, not a sample.
"""

from __future__ import annotations

import logging

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .db import DB_ERRORS, get_connection
from .demo_job_manager import DemoJobManager
from .demo_sites import DEMO_FIXTURES, LEGACY_SLUG_REDIRECTS
from .site_magic import ArtifactStorage, NullArtifactStorage, NullSiteMagicQueue, SiteMagicQueue

logger = logging.getLogger("webstaffr.demo_router")

demo_router = APIRouter(tags=["demos"])


def _connection(request: Request):
    try:
        return get_connection(request.app.state.db_path)
    except DB_ERRORS as exc:
        logger.error("demo_db_connection_failed error_type=%s", type(exc).__name__)
        return None


def _manager(request: Request, conn) -> DemoJobManager:
    queue: SiteMagicQueue = getattr(request.app.state, "site_magic_queue", None) or NullSiteMagicQueue()
    storage: ArtifactStorage = getattr(request.app.state, "site_magic_artifact_storage", None) or NullArtifactStorage()
    return DemoJobManager(conn, queue=queue, artifact_storage=storage)


def _gallery_item(slug: str, fixture) -> str:
    # Plain hyphen, not an em-dash or its entity -- NETBUILD_GOVERNANCE.md
    # bans em-dashes unconditionally, entity-encoded included.
    return f'<li><a href="/demos/{slug}">{fixture.verified_facts["biz_name"]} - {fixture.industry_key}</a></li>'


_GALLERY_ITEMS = "".join(_gallery_item(slug, fixture) for slug, fixture in DEMO_FIXTURES.items())

_GALLERY_HTML = f"""<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Demo Sites | NetBuild.Pro</title></head>
<body>
<h1>Demo Sites</h1>
<p>Sample sites built by the same Site Magic pipeline that builds a real customer's site.</p>
<ul>{_GALLERY_ITEMS}</ul>
<p><a href="/agency">Back to NetBuild.Pro</a></p>
</body>
</html>"""


def _building_html(slug: str, biz_name: str) -> str:
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta http-equiv="refresh" content="5">
<title>Building demo | NetBuild.Pro</title>
</head>
<body>
<h1>Building the {biz_name} demo</h1>
<p>This sample site is being generated now. This page refreshes automatically -- check back in a moment.</p>
<p><a href="/demos">All demos</a></p>
</body>
</html>"""


def _failed_html(slug: str, biz_name: str) -> str:
    return f"""<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Demo unavailable | NetBuild.Pro</title></head>
<body>
<h1>This demo is temporarily unavailable</h1>
<p>The {biz_name} sample site could not be built right now. Our team has been notified.</p>
<p><a href="/demos">All demos</a></p>
</body>
</html>"""


@demo_router.get("/demos", response_class=HTMLResponse)
async def demo_gallery() -> HTMLResponse:
    return HTMLResponse(content=_GALLERY_HTML)


@demo_router.get("/demos/{slug}", response_class=HTMLResponse)
async def demo_site(slug: str, request: Request) -> HTMLResponse:
    if slug in LEGACY_SLUG_REDIRECTS:
        return RedirectResponse(url=f"/demos/{LEGACY_SLUG_REDIRECTS[slug]}", status_code=301)

    fixture = DEMO_FIXTURES.get(slug)
    if fixture is None:
        return HTMLResponse(content=_failed_html(slug, "requested"), status_code=404)

    conn = _connection(request)
    if conn is None:
        return HTMLResponse(content=_building_html(slug, fixture.verified_facts["biz_name"]), status_code=503)

    try:
        manager = _manager(request, conn)
        result = manager.get_status(fixture.reserved_tenant_id)
        if result.status == "not_started":
            result = manager.enqueue_if_needed(fixture)
    finally:
        conn.close()

    biz_name = fixture.verified_facts["biz_name"]
    if result.status == "ready" and result.published_url:
        return RedirectResponse(url=result.published_url, status_code=302)
    if result.status == "failed":
        logger.error(
            "demo_build_failed slug=%s tenant_id=%s failure_code=%s",
            slug, fixture.reserved_tenant_id, result.failure_code,
        )
        return HTMLResponse(content=_failed_html(slug, biz_name))
    return HTMLResponse(content=_building_html(slug, biz_name))


# Legacy pre-2026-08-09 demo URLs -- keep anything already handed to a
# prospect working rather than 404ing.
@demo_router.get("/demo-sites/{file_name}")
async def legacy_demo_file(file_name: str) -> RedirectResponse:
    slug = file_name.removesuffix(".html")
    canonical = LEGACY_SLUG_REDIRECTS.get(slug, slug)
    return RedirectResponse(url=f"/demos/{canonical}", status_code=301)
